export const MAX_DEPTH=64;const text=new TextDecoder("utf-8",{fatal:true});export class MsgpackError extends Error{}export function unpack(bytes){const r=reader(bytes);const value=r.read(0);if(r.at()!==bytes.length)throw new MsgpackError(`${bytes.length-r.at()} bytes after the value`);return value}function reader(bytes){const d=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let at=0;const take=n=>{if(at+n>bytes.length)throw new MsgpackError(`truncated: ${n} bytes wanted at ${at} of ${bytes.length}`);const from=at;at+=n;return from};const u8=()=>d.getUint8(take(1));const u16=()=>d.getUint16(take(2));const u32=()=>d.getUint32(take(4));const big=signed=>{const v=signed?d.getBigInt64(take(8)):d.getBigUint64(take(8));return v>=BigInt(Number.MIN_SAFE_INTEGER)&&v<=BigInt(Number.MAX_SAFE_INTEGER)?Number(v):v};const str=n=>text.decode(bytes.subarray(take(n),at));const bin=n=>bytes.subarray(take(n),at);const list=(n,depth)=>{const out=new Array(n);for(let k=0;k<n;k+=1)out[k]=read(depth+1);return out};const map=(n,depth)=>{const out={};for(let k=0;k<n;k+=1){const key=read(depth+1);const name=key instanceof Uint8Array?text.decode(key):typeof key==="string"||typeof key==="number"?String(key):null;if(name===null)throw new MsgpackError("a map key that is not a string, bytes or an integer");out[name]=read(depth+1)}return out};function read(depth){if(depth>MAX_DEPTH)throw new MsgpackError(`nested deeper than ${MAX_DEPTH} levels`);const c=u8();if(c<=127)return c;if(c>=224)return c-256;if((c&224)===160)return str(c&31);if((c&240)===144)return list(c&15,depth);if((c&240)===128)return map(c&15,depth);switch(c){case 192:return null;case 194:return false;case 195:return true;case 196:return bin(u8());case 197:return bin(u16());case 198:return bin(u32());case 202:return d.getFloat32(take(4));case 203:return d.getFloat64(take(8));case 204:return u8();case 205:return u16();case 206:return u32();case 207:return big(false);case 208:return d.getInt8(take(1));case 209:return d.getInt16(take(2));case 210:return d.getInt32(take(4));case 211:return big(true);case 217:return str(u8());case 218:return str(u16());case 219:return str(u32());case 220:return list(u16(),depth);case 221:return list(u32(),depth);case 222:return map(u16(),depth);case 223:return map(u32(),depth);default:throw new MsgpackError(`msgpack type 0x${c.toString(16)} is not read here (extension types and the unused code)`)}}return{read:read,at:()=>at}}export function arrayOf(m){if(!m||typeof m!=="object"||m.nd!==true||typeof m.type!=="string"||!Array.isArray(m.shape)||!(m.data instanceof Uint8Array))return null;return{dtype:m.type,shape:m.shape,data:m.data}}